        balance += operation
        if balance < 0:
            return True
    return False

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the dp table with -inf to represent impossible states
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]

    # Base case: starting point
    dp[0][0][0] = grid[0][0]

    # Fill the dp table
    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N:
                    continue
                if grid[i1][j1] == -1 or grid[i2][j2] == -1:
                    dp[i1][j1][i2] = -float('inf')
                    continue
                if i1 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1-1][j1][i2])
                if j1 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1-1][i2])
                if i2 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1][i2-1])
                if j2 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1][i2][j2-1])

                if dp[i1][j1][i2] == -float('inf'):
                    continue

                if i1 == i2 and j1 == j2:
                    dp[i1][j1][i2] += grid[i1][j1]
                else:
                    dp[i1][j1][i2] += grid[i1][j1] + grid[i2][j2]

    return max(dp[N-1][N-1][i] for i in range(N))

