def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Extend the beads array to handle circular nature
    beads = beads + beads[:-1]
    n_extended = len(beads)

    # Dynamic programming table
    dp = [[0] * n_extended for _ in range(n_extended)]

    # Fill the dp table
    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

