def decode(encoded: str, original: str, message: str) -> str:
    # Check if the lengths of encoded and original are the same
    if len(encoded) != len(original):
        return "Failed"

    # Create a mapping from encoded to original characters
    encoding_map = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in encoding_map:
            if encoding_map[enc_char] != orig_char:
                return "Failed"
        else:
            encoding_map[enc_char] = orig_char

    # Check if all characters in the message are in the encoding map
    for char in message:
        if char not in encoding_map:
            return "Failed"

    # Decode the message using the mapping
    decoded_message = ''.join(encoding_map[char] for char in message)

    return decoded_message

